package oauth2

const signinPage = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Sign in with Nostr</title><style>body{background:#0d1117;color:#c9d1d9;font:16px system-ui;display:grid;place-items:center;min-height:100vh}.card{background:#161b22;border:1px solid #30363d;border-radius:12px;padding:2rem;max-width:420px;width:90%}button,input{box-sizing:border-box;width:100%;padding:.8rem;margin:.4rem 0;border-radius:7px}.tabs{display:flex}.tabs button{background:#21262d;color:#ddd;border:1px solid #30363d}.primary{background:#6f42c1;color:white;border:0}.panel{display:none}.panel.active{display:block}#status{min-height:1.3em;color:#f85149}</style></head><body><main class="card"><h2>Sign in with Nostr</h2><div class="tabs"><button onclick="show('nip07')">NIP-07 extension</button><button onclick="show('nip46')">NIP-46 signer</button></div><section id="nip07" class="panel active"><button class="primary" onclick="nip07()">Sign with browser extension</button></section><section id="nip46" class="panel"><input id="bunker" placeholder="bunker://…"><button class="primary" onclick="nip46()">Connect remote signer</button></section><p id="status"></p></main><script>const C=__CHALLENGE__;function show(id){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active')}function status(s){document.getElementById('status').textContent=s}async function submit(ev){let r=await fetch(C.url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({signed_event:ev})}),b=await r.json();if(!r.ok)throw Error(b.error);location.href=b.redirect_url}async function nip07(){try{if(!window.nostr)throw Error('No NIP-07 extension detected');status('Waiting for signature…');let pk=await nostr.getPublicKey(),ev=await nostr.signEvent({kind:27235,created_at:Math.floor(Date.now()/1000),tags:[['u',C.url],['method','POST'],['nonce',C.nonce]],content:'',pubkey:pk});await submit(ev)}catch(e){status(e.message)}}async function nip46(){let u=document.getElementById('bunker').value.trim();if(!u)return;let r=await fetch('/auth/nip46/init',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({bunker_uri:u,redirect_uri:C.flow})}),b=await r.json();if(!r.ok){status(b.error);return}status('Approve in your remote signer…');let poll=async()=>{let x=await fetch('/auth/oauth2/nip46/status?session='+encodeURIComponent(b.session_token)),y=await x.json();if(y.status==='complete'){location.href=y.redirect_url;return}if(y.status==='error'){status(y.error);return}setTimeout(poll,1000)};poll()}</script></body></html>`
